const https = require("https");
const http = require("http");
const fs = require("fs");
const path = require("path");

const headers = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
  "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"
};

function generateVisitorId() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    return (c === "x" ? r : r & 3 | 8).toString(16);
  });
}

function extractVideoId(url) {
  try {
    const parsed = new URL(url);
    const id = parsed.searchParams.get("id");
    if (id) return id;
    const pathParts = parsed.pathname.split("/").filter(Boolean);
    if (pathParts.length > 0) return pathParts[pathParts.length - 1];
    return null;
  } catch {
    return null;
  }
}

function getVideoExtension(videoId) {
  if (!videoId) return "mp4";
  if (videoId.length === 8 || (videoId.length === 9 && videoId.endsWith("1"))) return "mp4";
  if (videoId.length === 9 && videoId.endsWith("2")) return "mov";
  return "mp4";
}

async function fetchPage(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return fetchPage(res.headers.location).then(resolve).catch(reject);
      }
      let data = "";
      res.on("data", (chunk) => data += chunk);
      res.on("end", () => resolve({ status: res.statusCode, data }));
    }).on("error", reject);
  });
}

function buildMultipartBody(filePath, boundary) {
  const fileName = path.basename(filePath);
  const fileData = fs.readFileSync(filePath);
  const parts = [];
  parts.push(Buffer.from(`--${boundary}\r\n`));
  parts.push(Buffer.from(`Content-Disposition: form-data; name="file"; filename="${fileName}"\r\n`));
  parts.push(Buffer.from("Content-Type: video/mp4\r\n\r\n"));
  parts.push(fileData);
  parts.push(Buffer.from("\r\n"));
  parts.push(Buffer.from(`--${boundary}--\r\n`));
  return Buffer.concat(parts);
}

async function videyUpload(filePath, apiKey, apiSecret) {
  const visitorId = generateVisitorId();
  const boundary = "----FormBoundary" + Math.random().toString(36).slice(2);
  const body = buildMultipartBody(filePath, boundary);
  const uploadHeaders = {
    "Content-Type": `multipart/form-data; boundary=${boundary}`,
    "Content-Length": body.length,
    "User-Agent": headers["User-Agent"],
    "Origin": "https://videy.co",
    "Referer": "https://videy.co/"
  };
  if (apiKey) uploadHeaders["X-API-KEY"] = apiKey;
  if (apiSecret) uploadHeaders["X-API-SECRET"] = apiSecret;

  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: "videy.co",
      path: `/api/upload?visitorId=${visitorId}`,
      method: "POST",
      headers: uploadHeaders
    }, (res) => {
      let data = "";
      res.on("data", (chunk) => data += chunk);
      res.on("end", () => {
        try {
          const json = JSON.parse(data);
          if (res.statusCode === 200 && json.id) {
            resolve({
              status: true,
              id: json.id,
              link: json.link,
              cdnUrl: `https://cdn.videy.co/${json.id}.${getVideoExtension(json.id)}`
            });
          } else {
            resolve({ status: false, message: json.error || `Upload failed with status ${res.statusCode}` });
          }
        } catch {
          resolve({ status: false, message: `Invalid response: ${data}` });
        }
      });
    });
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

async function videyInfo(input) {
  try {
    let videoId = extractVideoId(input);
    if (!videoId) {
      if (/^[a-zA-Z0-9]{8,}$/.test(input)) {
        videoId = input;
      } else {
        return { status: false, message: "Invalid videy.co URL or video ID" };
      }
    }
    const ext = getVideoExtension(videoId);
    const cdnUrl = `https://cdn.videy.co/${videoId}.${ext}`;
    const videoPageUrl = `https://videy.co/v?id=${videoId}`;
    const result = {
      videoId,
      cdnUrl,
      videoPageUrl,
      uploader: null,
      note: "videy.co does not expose uploader/author info through public API. Videos are served directly from CDN without metadata lookup."
    };

    try {
      const page = await fetchPage(videoPageUrl);
      if (page.status === 200) {
        const ogMeta = page.data.match(/<meta\s+(?:property|name)="og:(\w+)"\s+content="([^"]+)"/gi);
        if (ogMeta) {
          for (const meta of ogMeta) {
            const match = meta.match(/content="([^"]+)"/);
            if (match && match[1]) {
              if (meta.includes("title")) result.title = match[1];
              if (meta.includes("description")) result.description = match[1];
              if (meta.includes("image")) result.thumbnail = match[1];
            }
          }
        }
        const titleMatch = page.data.match(/<title>([^<]+)<\/title>/i);
        if (titleMatch && titleMatch[1]) result.title = titleMatch[1];
      }
    } catch {
      // Page fetch failed, continue with basic info
    }

    return result;
  } catch (error) {
    return { status: false, message: error.message };
  }
}

