    .catch((err) => {
      console.log(JSON.stringify({ status: false, message: err.message }, null, 2));
      process.exit(1);
    });
} else if (command === "upload") {
  const filePath = args[1];
  const apiKey = args[2] || null;
  const apiSecret = args[3] || null;
  if (!filePath) {
    console.log(JSON.stringify({ status: false, message: "File path required" }, null, 2));
    process.exit(1);
  }
  if (!fs.existsSync(filePath)) {
    console.log(JSON.stringify({ status: false, message: `File not found: ${filePath}` }, null, 2));
    process.exit(1);
  }
  const stat = fs.statSync(filePath);
  if (stat.size > 100 * 1024 * 1024) {
    console.log(JSON.stringify({ status: false, message: "File too large. Maximum size is 100MB." }, null, 2));
    process.exit(1);
  }
  videyUpload(filePath, apiKey, apiSecret)
    .then((data) => console.log(JSON.stringify(data, null, 2)))
    .catch((err) => {
      console.log(JSON.stringify({ status: false, message: err.message }, null, 2));
      process.exit(1);
    });
} else {
  console.log(JSON.stringify({ status: false, message: `Unknown command: ${command}` }, null, 2));
  console.log("Use --help for usage information.");
  process.exit(1);
}
